var pInd, numClrs, maxD;
var palette = [
	["red", "purple"],
	["red", "yellow"],
	["yellow", "green"],
	["green", "blue"],
	["yellow", "blue"]
]

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(60);
	maxD = max(width, height) * 0.5;
	strokeWeight(maxD * 0.05);
	strokeCap(SQUARE);
	colorMode(HSB, 100)
	initValues();
}

function mousePressed() {
	if (mouseButton === LEFT) initValues()
}

function initValues() {
	background(222); // "beige");
	pInd = floor(random(palette.length));
	numClrs = floor(random(3, 16))
}

function draw() {
	// background("beige");
	translate(width/2, height/2);
	const ang = random(TWO_PI);
	const len = random(maxD);
	const px = cos(ang) * len;
	const py = sin(ang) * len;
	stroke(lerpColor(color(palette[pInd][0]), color(palette[pInd][1]), floor(random(numClrs))/(numClrs-1)));
	line(0, 0, px, py);
	// // noLoop() removed for animation
}
